1	// Wealth Simple Credit Card CSV Parser - #{#wsp1a}
2	// Expected format: "transaction_date","post_date","type","details","amount","currency"
3	// Date format: YYYY-MM-DD (e.g., "2025-12-13")
4	// Amount sign varies across CSV exports — the parser uses the "type" column to enforce:
5	//   Purchase → negative (expense), Payment/Refund → positive (credit)
6	
7	import { BaseCSVParser } from './BaseCSVParser';
8	import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';
9	
10	export class WealthSimpleParser extends BaseCSVParser {
11		private readonly EXPECTED_COLUMNS = [
12			'transaction_date',
13			'post_date',
14			'type',
15			'details',
16			'amount',
17			'currency'
18		];
19	
20		// #{#wsp2a} Format validation
21		validateFormat(csvContent: string): boolean {
22			try {
23				const cleanContent = this.removeBOM(csvContent);
24				const rows = this.parseCSV(cleanContent);
25	
26				if (rows.length === 0) return false;
27	
28				const header = rows[0];
29				return this.hasExpectedColumns(header, this.EXPECTED_COLUMNS);
30			} catch {
31				return false;
32			}
33		}
34	
35		// #{#wsp2b} Transaction parsing
36		parse(csvContent: string): CSVParseResult {
37			const transactions: ParsedTransaction[] = [];
38			const errors: string[] = [];
39	
40			const cleanContent = this.removeBOM(csvContent);
41			const rows = this.parseCSV(cleanContent);
42	
43			// Skip header row and parse data rows
44			for (let i = 1; i < rows.length; i++) {
45				const row = rows[i];
46				const rowNumber = i + 1;
47	
48				// Skip empty rows
49				if (!row || row.every((cell) => !cell?.trim())) {
50					continue;
51				}
52	
53				// Validate row has enough columns (at least 5 for the data we need)
54				if (row.length < 5) {
55					errors.push(`Row ${rowNumber}: Incomplete row (expected 6 columns, got ${row.length})`);
56					continue;
57				}
58	
59				// Parse transaction_date (YYYY-MM-DD format) from column 0
60				const dateStr = row[0]?.trim();
61				const transactionDate = this.parseDate(dateStr);
62				if (!transactionDate) {
63					errors.push(`Row ${rowNumber}: Invalid transaction_date "${dateStr}"`);
64					continue;
65				}
66	
67				// Parse vendor_name from details column (column 3)
68				const vendorName = row[3]?.trim();
69				if (!vendorName) {
70					errors.push(`Row ${rowNumber}: Missing details/vendor name`);
71					continue;
72				}
73	
74				// Parse type from column 2 (Purchase, Payment, Refund initiated, Refund settled)
75				const txnType = row[2]?.trim().toLowerCase() || '';
76	
77				// Parse amount from column 4
78				const amountStr = row[4]?.trim();
79				const rawAmount = this.parseAmount(amountStr);
80				if (rawAmount === null) {
81					errors.push(`Row ${rowNumber}: Invalid amount "${amountStr}"`);
82					continue;
83				}
84	
85				// Wealth Simple CSV exports use inconsistent signs across downloads.
86				// Use the type column to enforce correct sign: (#{#wsp1a})
87				//   Purchase → negative (expense)
88				//   Payment, Refund → positive (credit)
89				const absAmount = Math.abs(rawAmount);
90				const normalizedAmount =
91					absAmount === 0 ? 0 : txnType === 'purchase' ? -absAmount : absAmount;
92	
93				transactions.push({
94					transaction_date: transactionDate,
95					vendor_name: vendorName,
96					amount: normalizedAmount
97				});
98			}
99	
100			return { transactions, errors };
101		}
102	}
