6	describe('WealthSimpleParser', () => {
7		const parser = new WealthSimpleParser();
8	
9		// Helper to load CSV files from resources
10		const loadCSV = (filename: string): string => {
11			const filePath = join(process.cwd(), 'resources', filename);
12			return readFileSync(filePath, 'utf-8');
13		};
14	
15		describe('validateFormat - #{#wsp2a}', () => {
16			it('should validate correct Wealth Simple CSV format', () => {
17				const csv =
18					'"transaction_date","post_date","type","details","amount","currency"\n' +
19					'"2025-12-13","2025-12-14","Purchase","LCBO/RAO #0556","18.9","CAD"';
20				expect(parser.validateFormat(csv)).toBe(true);
21			});
22	
23			it('should reject invalid CSV format (missing columns)', () => {
24				const invalidCSV = '"transaction_date","amount"\n"2025-12-13","18.9"';
25				expect(parser.validateFormat(invalidCSV)).toBe(false);
26			});
27	
28			it('should handle case-insensitive headers', () => {
29				const csv =
30					'"TRANSACTION_DATE","POST_DATE","TYPE","DETAILS","AMOUNT","CURRENCY"\n' +
31					'"2025-12-13","2025-12-14","Purchase","TEST","18.9","CAD"';
32				expect(parser.validateFormat(csv)).toBe(true);
33			});
34	
35			it('should reject empty CSV', () => {
36				expect(parser.validateFormat('')).toBe(false);
37			});
38	
39			it('should handle CSV with BOM', () => {
40				const csv =
41					'\uFEFF"transaction_date","post_date","type","details","amount","currency"\n' +
42					'"2025-12-13","2025-12-14","Purchase","TEST","18.9","CAD"';
43				expect(parser.validateFormat(csv)).toBe(true);
44			});
45	
46			it('should reject CSV with only some required columns', () => {
47				const invalidCSV =
48					'"transaction_date","post_date","type"\n' + '"2025-12-13","2025-12-14","Purchase"';
49				expect(parser.validateFormat(invalidCSV)).toBe(false);
50			});
51	
52			it('should validate actual WealthSimple.csv sample file', () => {
53				const csv = loadCSV('WealthSimple.csv');
54				expect(parser.validateFormat(csv)).toBe(true);
55			});
56		});
57	
58		describe('parse - #{#wsp2b}', () => {
59			it('should parse valid Wealth Simple CSV', () => {
60				const csv =
61					'"transaction_date","post_date","type","details","amount","currency"\n' +
62					'"2025-12-13","2025-12-14","Purchase","LCBO/RAO #0556","-18.9","CAD"\n' +
63					'"2025-12-22","2025-12-23","Purchase","BULK BARN #507","-18.27","CAD"';
64	
65				const result = parser.parse(csv);
66	
67				expect(result.transactions).toHaveLength(2);
68				expect(result.errors).toHaveLength(0);
69	
70				expect(result.transactions[0]).toEqual({
71					transaction_date: '2025-12-13',
