214			it('should enforce sign based on type column regardless of CSV sign - #{#wsp1a}', () => {
215				const csv =
216					'"transaction_date","post_date","type","details","amount","currency"\n' +
217					'"2025-12-13","2025-12-14","Purchase","EXPENSE","50.00","CAD"\n' +
218					'"2025-12-13","2025-12-14","Purchase","EXPENSE2","-50.00","CAD"\n' +
219					'"2025-12-13","2025-12-14","Refund","REFUND","25.00","CAD"\n' +
220					'"2025-12-13","2025-12-14","Payment","PAYMENT","-100.00","CAD"';
